def find_redundant_connection(edges):
    adj = defaultdict(list)
    for a, b in edges:
        seen, stack = {a}, [a]
        while stack:
            for nb in adj[stack.pop()]:
                if nb not in seen:
                    seen.add(nb)
                    stack.append(nb)
        if b in seen:
            return [a, b]
        adj[a].append(b)
        adj[b].append(a)

def find_redundant_connection(edges):
    adj = defaultdict(set)
    for a, b in edges:
        adj[a].add(b)
        adj[b].add(a)
    degree = {v: len(nb) for v, nb in adj.items()}
    queue = deque(v for v, d in degree.items() if d == 1)
    removed = set()
    while queue:
        v = queue.popleft()
        removed.add(v)
        for nb in adj[v]:
            if nb not in removed:
                degree[nb] -= 1
                if degree[nb] == 1:
                    queue.append(nb)
    for a, b in reversed(edges):
        if a not in removed and b not in removed:
            return [a, b]

def find_redundant_connection(edges):
    parent = list(range(len(edges) + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]
        parent[ra] = rb
